<script setup lang="ts">
import {ref,reactive,computed,watch,onUnmounted} from 'vue'
import {ElMessageBox} from 'element-plus'
import {useUserStore} from '@/store/user'
import {usePermissionStore} from '@/store/permission'
import {knowledgeOrigin,knowledgePage,knowledgeDetail,knowledgeLatest,knowledgeDecision,knowledgeStoreOptions,knowledgeRecoveryApi} from '@/api/knowledge'
import {knowledgeContent,longId} from '@/api/knowledge-contract'
import type {KnowledgeContent,KnowledgeRevision} from '@/api/knowledge-contract'
import {createKnowledgeDraftRecovery} from '@/utils/knowledge-draft'
import type {KnowledgePending} from '@/utils/knowledge-draft'
const user=useUserStore(),permissions=usePermissionStore(),recovery=createKnowledgeDraftRecovery(localStorage)
const has=(code:string)=>permissions.permissions.includes('agronomy:knowledge:'+code)
const canRead=computed(()=>has('query')),canWrite=computed(()=>canRead.value&&has('write')),canReview=computed(()=>canRead.value&&has('review')),canPublish=computed(()=>canRead.value&&has('publish'))
const roleStamp=()=>JSON.stringify(user.userInfo?.extra?.roleCodes??[])
const isAdmin=computed(()=>Array.isArray(user.userInfo?.extra?.roleCodes)&&user.userInfo.extra.roleCodes.some(c=>c==='ADMIN'||c==='SUPER_ADMIN'))
const canStoreList=computed(()=>canRead.value&&isAdmin.value&&permissions.permissions.includes('store:list'))
function safeId(value:unknown){const s=typeof value==='number'&&Number.isSafeInteger(value)?String(value):value;return longId(s)?s:''}
const actorId=()=>safeId(user.userInfo?.id),ownStore=()=>safeId(user.userInfo?.extra?.storeId)
const selectedStore=ref(ownStore()),storeOptions=ref<{id:string;name:string}[]>([]),rows=ref<KnowledgeRevision[]>([]),nextAfter=ref<string|null>(null),detail=ref<KnowledgeRevision|null>(null)
const loading=ref(false),detailLoading=ref(false),busy=ref(false),storageBlocked=ref(false),pending=ref<KnowledgePending|null>(null),error=ref(''),message=ref('')
const editing=ref<{logicalKey:string|null;storeId:string;latest:number;source:number|null}|null>(null)
const emptyContent=():KnowledgeContent=>({title:'',summary:'',crop:'',region:'',growthStage:'',appliesTo:'',exclusions:'',body:'',sourceText:'',audience:'INTERNAL',riskLevel:'REQUIRES_HUMAN',effectiveFrom:null,effectiveUntil:null})
const draft=reactive<KnowledgeContent>(emptyContent())
const labels:Record<string,string>={DRAFT:'草稿',REVIEWED:'已审核',PUBLISHED:'已发布',WITHDRAWN:'已撤回',EXPIRED:'已超过适用期限'}
const actionLabels={review:'审核',publish:'发布',withdraw:'撤回'} as const
type Action=keyof typeof actionLabels
const decisionOpen=ref(false),decisionUnknown=ref(false),decisionAction=ref<Action>('review'),decisionRow=ref<KnowledgeRevision|null>(null),reason=ref(''),confirmed=ref(false)
let alive=true,epoch=0,listRun=0,detailRun=0,storeRun=0,lastIdentity=''
const capture=()=>({token:user.token,actor:actorId(),own:ownStore(),roles:roleStamp(),store:selectedStore.value,origin:knowledgeOrigin(),permissions:permissions.permissions.join('|'),epoch})
const current=(s:ReturnType<typeof capture>)=>alive&&!!s.token&&!!s.actor&&canRead.value&&s.token===user.token&&s.actor===actorId()&&s.own===ownStore()&&s.roles===roleStamp()&&s.store===selectedStore.value&&s.origin===knowledgeOrigin()&&s.permissions===permissions.permissions.join('|')&&s.epoch===epoch
const owner=(s:ReturnType<typeof capture>)=>({actorId:s.actor,origin:s.origin})
function restoreLocal(){const s=capture();if(!current(s))return;const original=pending.value;try{const value=recovery.restore(owner(s));if(original&&JSON.stringify(value)!==JSON.stringify(original))throw Error('replaced');pending.value=value;storageBlocked.value=false}catch{pending.value=original;storageBlocked.value=true;error.value='本机原稿记录暂时无法核对或已被替换。原请求已保留，请重试读取，不能覆盖保存。'}}
async function loadPage(more=false){const s=capture(),run=++listRun;if(!current(s))return;loading.value=true;error.value='';if(!more){rows.value=[];nextAfter.value=null}
 try{const value=await knowledgePage(selectedStore.value||null,more?nextAfter.value:null,s.token);if(current(s)&&run===listRun){rows.value=more?[...rows.value,...value.rows]:value.rows;nextAfter.value=value.nextAfter}}
 catch{if(current(s)&&run===listRun)error.value='知识列表未能读取，请刷新重试。'}finally{if(current(s)&&run===listRun)loading.value=false}}
async function searchStores(keyword=''){const s=capture(),run=++storeRun;if(!current(s)||!canStoreList.value)return;try{const value=await knowledgeStoreOptions(keyword,s.token);if(current(s)&&run===storeRun)storeOptions.value=value}catch{if(current(s)&&run===storeRun)error.value='门店选项未能读取，请重试搜索。'}}
async function openRow(row:KnowledgeRevision){if(busy.value||pending.value||storageBlocked.value||editing.value)return;const s=capture(),run=++detailRun;if(!current(s))return;detail.value=null;detailLoading.value=true;decisionOpen.value=false;confirmed.value=false;error.value='';
 try{const value=await knowledgeDetail(row.logicalKey,row.revision,s.token);if(current(s)&&run===detailRun)detail.value=value}catch{if(current(s)&&run===detailRun)error.value='版本详情未能读取，请重新选择。'}finally{if(current(s)&&run===detailRun)detailLoading.value=false}}
function beginNew(){if(!canWrite.value||busy.value||pending.value||storageBlocked.value||editing.value)return;const s=capture();if(!current(s))return;const store=selectedStore.value||ownStore();if(!store){error.value='请先选择门店，或请管理员分配当前门店。';return}editing.value={logicalKey:null,storeId:store,latest:0,source:null};Object.assign(draft,emptyContent());decisionOpen.value=false;error.value='';message.value=''}
async function beginRevision(){if(!canWrite.value||!detail.value||busy.value||pending.value||storageBlocked.value||editing.value)return;const s=capture(),original=JSON.parse(JSON.stringify(detail.value)) as KnowledgeRevision,run=++detailRun;if(!current(s))return;detailLoading.value=true;
 try{const latest=await knowledgeLatest(original.logicalKey,s.token);if(!current(s)||run!==detailRun)return;if(latest.storeId!==original.storeId)throw Error('changed');editing.value={logicalKey:original.logicalKey,storeId:original.storeId,latest:latest.revision,source:original.revision};Object.assign(draft,knowledgeContent(original.content));decisionOpen.value=false;error.value=''}catch{if(current(s)&&run===detailRun)error.value='最新版本未能核对，请重新读取后再编辑。'}finally{if(current(s)&&run===detailRun)detailLoading.value=false}}
async function cancelEditor(){if(!editing.value||pending.value||busy.value)return;const s=capture(),original=editing.value;try{if(draft.title||draft.body)await ElMessageBox.confirm('未保存的修改将被舍弃。已保存版本不会改变。','放弃当前编辑',{confirmButtonText:'放弃编辑',cancelButtonText:'继续编辑',type:'warning'});if(current(s)&&editing.value===original)editing.value=null}catch{/* 继续编辑。 */}}
function applySaved(result:Awaited<ReturnType<typeof recovery.query>>){if(result.state==='SAVED'){pending.value=null;editing.value=null;detail.value=result.revision;restoreLocal();message.value=`原稿已核实为第${result.revision.revision}版，当前状态：${labels[result.revision.effectiveState]}。${pending.value?'另有原稿待核对，请继续逐一核实。':''}`;void loadPage()}else if(result.state==='DISCARDED_STALE'){pending.value=null;editing.value=null;restoreLocal();message.value='已核对更新版本及原请求，旧稿等待已结束。'+(pending.value?'另有原稿待核对。':'可重新选择版本编辑。')}else{pending.value=result.pending;message.value='原保存结果仍未确认。请保留原稿，按原内容重试或稍后再核对。'}}
async function saveDraft(){const s=capture();if(!current(s)||!canWrite.value||!editing.value||pending.value||busy.value||storageBlocked.value)return;try{const content=knowledgeContent(draft);pending.value=recovery.prepare(owner(s),editing.value.logicalKey,editing.value.storeId,editing.value.latest,content)}catch{restoreLocal();if(!storageBlocked.value)error.value='请核对标题、字段长度及日期格式；原稿未能可靠准备，不会发送保存请求。';return}
 busy.value=true;error.value='';try{const result=await recovery.retry(owner(s),s.token,()=>current(s),knowledgeRecoveryApi);if(current(s))applySaved(result)}catch{if(current(s)){restoreLocal();error.value='保存结果未能确认。请先核对原稿，不要重新填写或重复保存。'}}finally{if(current(s))busy.value=false}}
async function runPending(action:'query'|'retry'|'close'){const s=capture();if(!current(s)||!pending.value||busy.value||storageBlocked.value||action!=='query'&&!canWrite.value)return;busy.value=true;error.value='';
 try{if(action==='close'){await ElMessageBox.confirm('仅在服务器已存在更新版本，且原保存仍无结果时结束旧稿等待；原稿若已保存则展示原结果。','核对并结束旧稿等待',{confirmButtonText:'核对后结束',cancelButtonText:'保留等待',type:'warning'});if(!current(s))return}const result=action==='query'?await recovery.query(owner(s),s.token,()=>current(s),knowledgeRecoveryApi):action==='retry'?await recovery.retry(owner(s),s.token,()=>current(s),knowledgeRecoveryApi):await recovery.discardStale(owner(s),s.token,()=>current(s),knowledgeRecoveryApi,true);if(current(s))applySaved(result)}catch{if(current(s)){restoreLocal();error.value='原稿尚未能核实或结束，等待记录已保留。请稍后核对或联系管理员。'}}finally{if(current(s))busy.value=false}}
function allowedAction(action:Action,row:KnowledgeRevision){return action==='review'?canReview.value&&row.state==='DRAFT':action==='publish'?canPublish.value&&row.state==='REVIEWED'&&(row.content.audience==='INTERNAL'||row.content.riskLevel==='LOW'):canPublish.value&&row.state!=='WITHDRAWN'}
function chooseDecision(action:Action){const s=capture();if(!current(s)||busy.value||decisionUnknown.value||pending.value||editing.value||!detail.value||!allowedAction(action,detail.value))return;decisionRow.value=JSON.parse(JSON.stringify(detail.value));decisionAction.value=action;reason.value='';confirmed.value=false;decisionOpen.value=true;error.value=''}
async function submitDecision(){const s=capture(),original=decisionRow.value,action=decisionAction.value;if(!current(s)||!decisionOpen.value||!original||busy.value||decisionUnknown.value||!confirmed.value||!reason.value.trim()||reason.value.length>500||!allowedAction(action,original))return;busy.value=true;error.value='';
 try{const value=await knowledgeDecision(original,action,reason.value,s.token);if(current(s)){detail.value=value;decisionOpen.value=false;confirmed.value=false;message.value=`当前第${value.revision}版已${actionLabels[action]}。`;void loadPage()}}catch{if(current(s)){decisionUnknown.value=true;confirmed.value=false;error.value='这次处理结果尚未确认。请读取当前状态，不要连续提交。'}}finally{if(current(s))busy.value=false}}
async function readDecision(){const s=capture(),original=decisionRow.value;if(!current(s)||!original||busy.value)return;busy.value=true;try{const value=await knowledgeDetail(original.logicalKey,original.revision,s.token);if(current(s)){detail.value=value;confirmed.value=false;decisionOpen.value=false;decisionUnknown.value=false;message.value=`已读取当前状态：${labels[value.effectiveState]}。先前操作结果仍请按当前事实核对，再决定下一步。`;error.value=''}}catch{if(current(s))error.value='当前状态未能读取，请保留等待并重试。'}finally{if(current(s))busy.value=false}}
watch(()=>[user.token,actorId(),ownStore(),roleStamp(),permissions.permissions.join('|'),selectedStore.value],()=>{++epoch;++listRun;++detailRun;++storeRun;rows.value=[];nextAfter.value=null;detail.value=null;editing.value=null;decisionOpen.value=false;confirmed.value=false;decisionUnknown.value=false;busy.value=false;loading.value=false;detailLoading.value=false;error.value='';message.value='';pending.value=null;storageBlocked.value=false;storeOptions.value=[];const identity=user.token+'|'+actorId()+'|'+ownStore()+'|'+roleStamp();if(identity!==lastIdentity){lastIdentity=identity;selectedStore.value=ownStore()}if(canRead.value&&user.token&&actorId()){restoreLocal();void loadPage();if(canStoreList.value)void searchStores()}},{immediate:true})
function closeDecision(value:boolean){if(!busy.value)decisionOpen.value=value}
onUnmounted(()=>{alive=false;++epoch;++listRun;++detailRun;++storeRun})
</script>
<template>
 <div class="app-page knowledge-page">
  <section class="page-header"><div><h1>农技知识</h1><p>修改内容另存新版本，审核后再发布。客户只看到适用范围内、仍有效的公开知识。</p></div><div class="knowledge-actions"><el-button @click="loadPage()" :loading="loading" :disabled="busy||!canRead">刷新</el-button><el-button type="primary" @click="beginNew" :disabled="!canWrite||busy||!!pending||storageBlocked||!!editing">新建知识草稿</el-button></div></section>
  <el-alert v-if="!canRead" title="需要农技知识查询权限，请联系管理员授权。" type="warning" :closable="false"/>
  <el-alert v-if="error" :title="error" type="warning" show-icon :closable="false"/><el-alert v-if="message" :title="message" type="info" :closable="false"/>
  <section v-if="decisionUnknown&&!decisionOpen" class="knowledge-wait"><strong>上次版本处理结果尚待核对</strong><p>{{decisionRow?.content.title}} · 第{{decisionRow?.revision}}版。先读取当前状态，再处理其他版本。</p><el-button @click="readDecision" :loading="busy">读取当前状态</el-button></section>
  <section v-if="pending||storageBlocked" class="knowledge-wait" aria-live="polite"><strong>{{storageBlocked?'本机原稿暂时无法核对':'上次保存尚待核对'}}</strong><p v-if="pending">{{pending.command.content.title}} · 门店 #{{pending.command.storeId}}。先核对原稿，不要重新填写。</p><div class="knowledge-actions"><el-button v-if="storageBlocked" @click="restoreLocal">重新读取本机记录</el-button><template v-else><el-button @click="runPending('query')" :loading="busy">核对原保存</el-button><el-button @click="runPending('retry')" :disabled="busy||!canWrite">按原稿重试</el-button><el-button @click="runPending('close')" :disabled="busy||!canWrite">核对并结束旧稿等待</el-button></template></div></section>
  <div v-if="canRead" class="knowledge-layout">
   <section class="knowledge-list"><label v-if="canStoreList" class="knowledge-filter">门店<el-select v-model="selectedStore" clearable filterable remote :remote-method="searchStores" placeholder="全部门店，可输入名称搜索" :disabled="busy||!!editing||!!pending"><el-option v-for="store in storeOptions" :key="store.id" :value="store.id" :label="store.name"/></el-select></label><p v-else class="knowledge-muted">当前门店 #{{ownStore()||'未分配'}}</p>
    <el-skeleton v-if="loading&&!rows.length" :rows="5" animated/><el-empty v-else-if="!rows.length&&!error" description="暂无已保存的知识版本。先录入草稿，完善来源与适用范围后再审核。" :image-size="70"/>
    <ul><li v-for="row in rows" :key="row.id"><button class="knowledge-row" :class="{'is-selected':detail?.id===row.id}" :disabled="busy||!!pending||storageBlocked||!!editing" @click="openRow(row)"><strong>{{row.content.title}}</strong><span>第{{row.revision}}版 · {{labels[row.effectiveState]}} · 门店 #{{row.storeId}}</span><span>{{row.content.region||'地区未填'}} / {{row.content.crop||'作物未填'}} / {{row.content.growthStage||'阶段未填'}}</span><span>{{row.content.audience==='PUBLIC'?'拟公开给客户':'仅内部使用'}}</span></button></li></ul><el-button v-if="nextAfter" @click="loadPage(true)" :disabled="loading||busy||!!editing||!!pending">查看更多版本</el-button>
   </section>
   <section class="knowledge-panel">
    <template v-if="editing"><div class="knowledge-heading"><h2>{{editing.source?'以第'+editing.source+'版另存草稿':'新建知识草稿'}}</h2><span>门店 #{{editing.storeId}}</span></div><p class="knowledge-muted">保存后形成第{{editing.latest+1}}版草稿，原已发布内容不会被修改。</p>
     <el-form label-position="top" :disabled="busy||!!pending||storageBlocked"><el-form-item label="知识标题（必填）"><el-input v-model="draft.title" maxlength="200" show-word-limit/></el-form-item><el-form-item label="一句话摘要"><el-input v-model="draft.summary" type="textarea" :rows="2" maxlength="500" show-word-limit/></el-form-item>
      <div class="knowledge-fields"><el-form-item label="适用地区"><el-input v-model="draft.region" maxlength="100" placeholder="例如：大庆"/></el-form-item><el-form-item label="作物"><el-input v-model="draft.crop" maxlength="50" placeholder="例如：玉米"/></el-form-item><el-form-item label="生长阶段"><el-input v-model="draft.growthStage" maxlength="100" placeholder="请按实际阶段填写"/></el-form-item></div>
      <el-form-item label="适用条件"><el-input v-model="draft.appliesTo" type="textarea" :rows="3" maxlength="2000" show-word-limit/></el-form-item><el-form-item label="不适用条件及需要人工判断的情况"><el-input v-model="draft.exclusions" type="textarea" :rows="3" maxlength="2000" show-word-limit/></el-form-item><el-form-item label="正文与处理步骤"><el-input v-model="draft.body" type="textarea" :rows="9" maxlength="20000" show-word-limit/></el-form-item><el-form-item label="依据与来源"><el-input v-model="draft.sourceText" type="textarea" :rows="3" maxlength="2000" show-word-limit placeholder="填写可核对的来源及经验依据，不填写农户姓名、电话等个案隐私。"/></el-form-item>
      <div class="knowledge-fields"><el-form-item label="使用对象"><el-select v-model="draft.audience"><el-option value="INTERNAL" label="仅内部员工使用"/><el-option value="PUBLIC" label="拟公开给客户"/></el-select></el-form-item><el-form-item label="是否需要人工判断"><el-select v-model="draft.riskLevel"><el-option value="REQUIRES_HUMAN" label="需要人工处理，仅内部使用"/><el-option value="LOW" label="低风险标准知识"/></el-select></el-form-item></div>
      <div class="knowledge-fields"><el-form-item label="适用期限开始"><el-date-picker v-model="draft.effectiveFrom" type="date" value-format="YYYY-MM-DD" placeholder="审核前填写"/></el-form-item><el-form-item label="适用期限结束"><el-date-picker v-model="draft.effectiveUntil" type="date" value-format="YYYY-MM-DD" placeholder="审核前填写"/></el-form-item></div>
     </el-form><div class="knowledge-actions"><el-button @click="cancelEditor" :disabled="busy||!!pending">取消编辑</el-button><el-button type="primary" @click="saveDraft" :loading="busy" :disabled="!!pending||storageBlocked||!canWrite">保存为草稿</el-button></div>
    </template>
    <el-skeleton v-else-if="detailLoading" :rows="8" animated/><el-empty v-else-if="!detail" description="选择左侧版本，核对内容、来源与适用范围。" :image-size="80"/>
    <template v-else><div class="knowledge-heading"><h2>{{detail.content.title}}</h2><el-tag>{{labels[detail.effectiveState]}}</el-tag></div><p class="knowledge-muted">第{{detail.revision}}版 · 门店 #{{detail.storeId}} · {{detail.content.audience==='PUBLIC'?'客户公开知识':'内部知识'}}</p><p>{{detail.content.summary||'摘要尚未填写'}}</p><dl class="knowledge-facts"><div><dt>地区 / 作物 / 阶段</dt><dd>{{detail.content.region||'未填'}} / {{detail.content.crop||'未填'}} / {{detail.content.growthStage||'未填'}}</dd></div><div><dt>适用期限</dt><dd>{{detail.content.effectiveFrom||'未填'}} 至 {{detail.content.effectiveUntil||'未填'}}</dd></div><div><dt>人工判断</dt><dd>{{detail.content.riskLevel==='LOW'?'低风险标准知识':'需人工处理，不能直接公开'}}</dd></div><div><dt>审核时间</dt><dd>{{detail.reviewedAt?.replace('T',' ')||'尚未审核'}}</dd></div></dl>
     <h3>适用条件</h3><p class="knowledge-text">{{detail.content.appliesTo||'尚未填写'}}</p><h3>不适用条件</h3><p class="knowledge-text">{{detail.content.exclusions||'尚未填写'}}</p><h3>正文</h3><p class="knowledge-text">{{detail.content.body||'尚未填写'}}</p><h3>依据与来源</h3><p class="knowledge-text">{{detail.content.sourceText||'尚未填写'}}</p>
     <div class="knowledge-actions"><el-button v-if="canWrite" @click="beginRevision" :disabled="busy||!!pending||storageBlocked">以此内容另存新版本</el-button><el-button v-if="allowedAction('review',detail)" type="primary" @click="chooseDecision('review')" :disabled="busy||!!pending">审核此版本</el-button><el-button v-if="allowedAction('publish',detail)" type="primary" @click="chooseDecision('publish')" :disabled="busy||!!pending">发布此版本</el-button><el-button v-if="allowedAction('withdraw',detail)" @click="chooseDecision('withdraw')" :disabled="busy||!!pending">撤回此版本</el-button></div>
    </template>
   </section>
  </div>
  <el-dialog :model-value="decisionOpen" :title="actionLabels[decisionAction]+'知识版本'" width="min(620px, calc(100vw - 32px))" :show-close="!busy" :close-on-click-modal="!busy" :close-on-press-escape="!busy" @update:model-value="closeDecision"><template v-if="decisionRow"><h3>{{decisionRow.content.title}} · 第{{decisionRow.revision}}版</h3><p>{{decisionRow.content.region}} / {{decisionRow.content.crop}} / {{decisionRow.content.growthStage}}</p><p>{{decisionRow.content.audience==='PUBLIC'?'发布后符合范围的客户可以阅读。':'仅内部使用，不会进入客户公开查询。'}} {{decisionAction==='withdraw'?'撤回保留原文与处理记录，不能直接恢复旧版。':''}}</p><el-form label-position="top"><el-form-item label="核对经过与原因（必填）"><el-input v-model="reason" type="textarea" :rows="3" maxlength="500" :disabled="busy||decisionUnknown"/></el-form-item></el-form><el-checkbox v-model="confirmed" :disabled="busy||decisionUnknown">已核对本版本正文、来源、受众和适用期限，确认{{actionLabels[decisionAction]}}。</el-checkbox><p v-if="decisionUnknown" role="status">原处理结果尚未确认，请读取当前状态。</p></template><template #footer><el-button @click="decisionOpen=false" :disabled="busy">关闭</el-button><el-button v-if="decisionUnknown" @click="readDecision" :loading="busy">读取当前状态</el-button><el-button v-else type="primary" @click="submitDecision" :loading="busy" :disabled="!confirmed||!reason.trim()">确认{{actionLabels[decisionAction]}}</el-button></template></el-dialog>
 </div>
</template>
<style scoped>
